function MonComposant() {
  const [data, setData] = useState([]);

  useEffect(() => {
    fetch('https://api.exemple.com/data')
      .then(response => response.json())
      .then(data => setData(data));
  }, []);

  return (
    <ul>
      {data.map(item => <li key={item.id}>{item.nom}</li>)}
    </ul>
  );
}
```

